</svg></div>
    <div class="titulo">
        <h1>Tablero de Cuentas a Pagar</h1>
        <div class="subtitle">Cheques Galicia · Planillas de prestadores · Órdenes de Pago</div>
        <div class="meta" id="meta"></div>
